      SUBROUTINE ELICITCC     ACCUMULATES MATRICES WHEN NOT FITTINGCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'COCOM.CIN'      INCLUDE 'COP.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0D.CIN'      INCLUDE 'ELM7B.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ETACOM.CIN'      INCLUDE 'ETAP.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'R.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R0P.CIN'CC     LOCAL VARIABLESC      REAL  COT(6), COTF(6)CC------------------------------------------------------------------C     DETERMINE EFFECT OF ELEMENTC      CALL ELMENT(NWK)      IF (TYPE .LE. 0) GO TO 550      IF (FLUSHL) GO TO 550      IF (CFIT .AND. .NOT. RMTX) GO TO 520      IF (NWK .NE. 1) GO TO 550CC     MULTIPLY TRANSFER MATRICESC      IF (RAY) CALL THREAD(0,ETA)      IF (ALIGN) CALL RTORO      IF (SOFA) THEN        IF (R1P) THEN          DO 110 J = 1, 6  110     COTF(J) = COF(J)          CALL THRED1(R,COTF)        ENDIF        DO 113 J = 1, 6  113   COT(J) = CO(J)        CALL THREAD(0,COT)        IF (NORD1 .GE. 2 .AND. NORD2 .GE. 1) CALL ENRICH(0)      ENDIF      IF (NORD2 .GE. 1) CALL MRR2C      IF (SOFA) THEN        IF (R1P) THEN          IF (DCOV) THEN            DO 241 J = 1, 6  241       COF(J) = COTF(J) + COD(J)          ELSE            DO 242 J = 1, 6  242       COF(J) = COTF(J)          ENDIF        ENDIF        IF (DCOV) THEN          DO 265 J = 1, 6  265     CO(J) = COT(J) + COD(J)        ELSE          DO 270 J = 1, 6  270     CO(J) = COT(J)        ENDIF      ELSE IF (DCOV) THEN        IF (R1P) THEN          DO 273 J = 1, 6  273     COF(J) = COD(J)        ENDIF        DO 275 J = 1, 6  275   CO(J) = COD(J)        SOFA = .TRUE.        NORD1 = NORDX      ENDIFCC     ADVANCE TO NEXT ELEMENTC  500 IF (ALIGN) THEN        CALL ADVANC(2)        CALL ADVANC(3)      ENDIF  510 R2P = .TRUE.      R0P = .TRUE.  520 IF (LAY) CALL ADVANC(4)      IF (NM .GE. 1) CALL DAMAGE      DO 530 J = 1, 6  530 CONTINUEC  550 RETURN      END